package com.campuskart; import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*; @WebServlet("/mark-sold") public class MarkSoldServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE products SET status='SOLD',sold_at=NOW() WHERE id=? AND seller_id=? AND status='AVAILABLE'")){p.setInt(1,Integer.parseInt(r.getParameter("id")));p.setInt(2,(Integer)h.getAttribute("userId"));p.executeUpdate();s.sendRedirect("my-listings?success=Marked+as+sold");}catch(Exception e){throw new IOException(e);}}}